### 3. Plugging API com Axios

Crie um plugin global para configurar o Axios e usar interceptores para enviar tokens automaticamente nas requisições:

```ts
// plugins/axios.ts
import { ref } from 'vue';
import { createAxios } from '@vueuse/integrations/useAxios';

export const useApi = () => {
  return ref(createAxios({
    baseURL: process.env.API_URL || 'http://localhost:3000',
    timeout: 10000,
  }).get('/api/getUser'));
};
```

### 4. Autenticação com Pinia

No `stores/auth.store.ts`, implemente a lógica para gerenciar o estado do usuário e o token JWT.

```ts
// stores/auth.store.ts
import { defineStore } from 'pinia';
import { ref } from 'vue';

interface UserState {
  accessToken: string | null;
  user: any | null;
}

export const useAuthStore = defineStore('auth', () => {
  const { accessToken, user } = ref<UserState>({ accessToken: null, user: null });

  const setToken = (token: string) => {
    accessToken.value = token;
    localStorage.setItem('accessToken', token);
  };

  const removeToken = () => {
    accessToken.value = null;
    localStorage.removeItem('accessToken');
  };

  return {
    accessToken,
    user,
    setToken,
    removeToken,
  };
});
```

### 5. Middleware de Autenticação

O middleware garante que todas as páginas protegidas exijam uma sessão válida antes de carregar o conteúdo:

```ts
// middleware/auth.middleware.ts
import { defineNuxtRouteMiddleware } from '#imports';

export default defineNuxtRouteMiddleware((to) => {
  if (!localStorage.getItem('accessToken') && !['/', '/login'].includes(to.path)) {
    return '/login';
  }
});
```

